function updateWorkbookSlot(index,value){const {session,item}=workbookCurrent();if(!session||!item||session.results[item.key])return;const values=[...(session.responses[item.key]||Array(item.slotCount).fill(''))];values[index]=value;session.responses[item.key]=values;const submit=$('[data-submit-workbook]');if(submit)submit.disabled=!values.every(item=>String(item).trim());}
function syncWorkbookSlotWidth(input){const wrapper=input.closest('.workbook-blank');if(!wrapper)return;const slotCh=workbookSlotCh(input.value||input.placeholder||'답');wrapper.style.setProperty('--workbook-slot-ch',slotCh);wrapper.classList.toggle('long-slot',slotCh>24);}
function flashRecallWrong(input){input.classList.add('recall-wrong');const snapshot=input.value;setTimeout(()=>{if(input.value===snapshot)input.value='';input.classList.remove('recall-wrong');input.focus();},220);}
function handleWorkbookRecallInput(input){
  const {session,item}=workbookCurrent();
  if(!session||!item||session.results[item.key]||input.dataset.unlocking==='true')return;
  const index=Number(input.dataset.workbookSlot),mode=input.dataset.workbookRecall,cue=workbookRecallCue(input.value,mode),raw=String(input.value||'').trim();
  if(!raw)return;
  const answer=item.grading?.answers?.[index],expected=workbookRecallCue(answer,mode);
  if(!cue){if(input.dataset.composing!=='true')flashRecallWrong(input);return;}
  if(cue!==expected){if(input.dataset.composing!=='true')flashRecallWrong(input);return;}
  input.dataset.unlocking='true';updateWorkbookSlot(index,answer);input.value=answer;syncWorkbookSlotWidth(input);input.classList.add('recall-complete');input.readOnly=true;
  const next=document.querySelector(`[data-workbook-slot="${index+1}"]`);if(next)next.focus();
  const values=workbookValues(session,item);if(values.length===item.slotCount&&values.every(value=>String(value).trim()))submitWorkbook();
}
async function handleWorkbookLiveInput(input){const {session,item}=workbookCurrent();if(!session||!item||session.results[item.key])return;const index=Number(input.dataset.workbookSlot),value=input.value,assistance=workbookAssistanceState(session,item),sequence=(assistance.requestSequence[index]||0)+1;assistance.requestSequence[index]=sequence;syncWorkbookSlotWidth(input);updateWorkbookSlot(index,value);const live=await livePrefixState(value,item.assistance?.slots?.[index]);if(assistance.requestSequence[index]!==sequence)return;assistance.live[index]=live;const wrapper=input.closest('.workbook-blank');wrapper?.classList.toggle('live-mismatch',live.valid===false);let copy=wrapper?.querySelector('.workbook-live-copy');if(live.valid===false){if(!copy){copy=document.createElement('small');copy.className='workbook-live-copy';wrapper.append(copy);}copy.innerHTML=`<span>${esc(value.slice(0,live.mismatchIndex))}</span><b>${esc(value.slice(live.mismatchIndex))}</b>`;}else copy?.remove();}
async function requestWorkbookHint(){const {session,item}=workbookCurrent();if(!session||!item||Number(item.stage)!==9||session.results[item.key])return;const assistance=workbookAssistanceState(session,item);if(assistance.hintCount>=1)return revealWorkbookAnswer();const values=workbookValues(session,item),slots=Array.from({length:item.slotCount},(_,index)=>index).filter(index=>!String(values[index]||'').trim()||assistance.live[index]?.complete!==true);if(!slots.length)return submitWorkbook();const data=await safely(()=>call('workbook_hint',{examId:state.scope.id,passageId:session.passageId,itemKey:item.key,slots},state.token,'힌트를 준비하는 중…'));if(!data)return;assistance.hintCount=data.hintCount;assistance.usedFullAnswerHint=false;assistance.hintReceipt=data.hintReceipt;for(const hint of data.fragments||[])assistance.hints[hint.slot]=hint.fragment;renderWorkbook();requestAnimationFrame(()=>document.querySelector(`[data-workbook-slot="${slots[0]}"]`)?.focus());}
