  readerGlossController?.destroy();readerGlossController=null;
  if(!readerGlossEnabled()){const units=readerUnits(),lead=units.shift()||'',paragraphs=readerParagraphs(units);show('student-reader');$('#student-reader').innerHTML=`<button class="study-back" type="button" data-exit-study aria-label="학습 목록으로"><span aria-hidden="true">‹</span></button><div class="reader-shell reader-document"><p class="eyebrow">TEXTBOOK · READER</p><h1>${esc(state.passage.title)}</h1>${lead?`<p class="reader-lede">${esc(lead)}</p>`:''}<article class="reader-prose">${paragraphs.length?paragraphs.map(paragraph=>`<p>${esc(paragraph)}</p>`).join(''):`<p>${plainPassage()}</p>`}</article></div>`;return;}
  const sentences=state.sentences.map(sentence=>({id:sentence.id,text:String(sentence.text||'').trim(),translation:String(sentence.translation||'')})).filter(sentence=>sentence.text),lead=sentences.shift(),paragraphs=readerGlossParagraphs(sentences),root=$('#student-reader');show('student-reader');root.dataset.readerPassageId=state.passage.id;root.innerHTML=`<button class="study-back" type="button" data-exit-study aria-label="학습 목록으로"><span aria-hidden="true">‹</span></button><div class="reader-shell reader-document"><p class="eyebrow">TEXTBOOK · READER</p><h1>${esc(state.passage.title)}</h1>${lead?`<p class="reader-lede">${readerGlossSentenceHtml(lead)}</p>`:''}<article class="reader-prose">${paragraphs.length?paragraphs.map(paragraph=>`<p>${paragraph.map(readerGlossSentenceHtml).join(' ')}</p>`).join(''):'<p></p>'}</article><p class="reader-inline-notice" data-reader-gloss-notice hidden></p><span class="sr-only" data-reader-gloss-live aria-live="polite"></span></div>`;
