function applyPassage(data){Object.assign(state,{passage:data.passage,sentences:data.sentences||[],savedWords:data.savedWords||state.savedWords||[]});}
async function openPassageStudy(passageId){if(!state.scope)return;state.questionSession=null;const cached=cachedPassage(passageId);if(cached){applyPassage(cached);renderReader();}const data=await safely(()=>cached?readyApi('student_passage',{examId:state.scope.id,passageId},state.token):call('student_passage',{examId:state.scope.id,passageId},state.token,'지문을 준비하는 중…'));if(!data)return;applyPassage(data);renderReader();cachePassage(data);localStorage.setItem(`ready-last-passage:${state.student.id}:${state.scope.id}`,passageId);}

function questionPassageHtml(question,result,selected,inlineSelected=[],lookupText=null){return sharedQuestionPassageHtml(question,result,selected,inlineSelected,{escape:esc,lookupText});}
function questionSummaryHtml(question){return sharedQuestionSummaryHtml(question,{escape:esc});}
function responseArea(question,result,selected,choiceMarks=[],lookupText=null){return questionResponseAreaHtml(question,result,selected,choiceMarks,{escape:esc,lookupText});}
function hasResponse(question,selected,inlineSelected=[]){if(question.interaction==='inline_options'){const groups=question.interactionContract?.passage?.segments?.filter(segment=>segment.kind==='inline_options')||[];return inlineSelected.length===groups.length&&inlineSelected.every(Number.isInteger);}return question.responseType==='written'?contractResponseComplete(question.interactionContract,selected):Array.isArray(selected)&&selected.length>0;}
function resultFeedbackHtml(question,result){if(!result)return '';const explanation=String(result.explanation||'').trim(),action=explanation?`<div class="feedback-actions"><button type="button" data-toggle-explanation>${result.showExplanation?'해설 닫기':'해설 보기'}</button></div>`:'',revealed=result.showExplanation&&explanation?`<p class="explanation-reveal">${esc(explanation)}</p>`:'',ai=result.aiFeedback?`<p class="ai-grade-feedback"><strong>AI 채점</strong>${esc(result.aiFeedback)}</p>`:'';if(result.correct)return `<div class="question-feedback correct"><strong>정답입니다.</strong><span>북마크하면 Review에서 다시 볼 수 있습니다.</span>${ai}${action}${revealed}</div>`;return `<div class="question-feedback wrong"><strong>오답으로 기록했습니다.</strong><span>Review에 자동으로 저장했습니다.</span>${ai}${action}${revealed}</div>`;}
function questionOutcome(question,result){if(result)return result.correct?'correct':'wrong';return question.lastResult===true?'correct':question.lastResult===false?'wrong':'';}
function bookmarkIcon(active=false){return `<span class="bookmark-star" aria-hidden="true">${active?'★':'☆'}</span>`;}
function questionAiStatusHtml(session,question,ready){if(session.aiPending[question.id])return '<div class="local-ai-status" role="status"><strong>AI가 답안을 확인하고 있어요…</strong><span>작성한 답안은 그대로 유지됩니다.</span></div>';const error=session.aiErrors[question.id];if(error)return `<div class="local-ai-status error" role="status"><strong>${esc(error)}</strong><span>답안을 유지했어요. 연결 후 다시 제출해 주세요.</span></div>`;return `<button class="button primary question-submit" type="button" data-submit-question ${ready?'':'disabled'}>제출</button>`;}
function renderQuestion(){const session=state.questionSession;if(!session)return renderScope();readerGlossController?.destroy();readerGlossController=null;const item=session.items[session.index],question=item.question||item,result=session.results[question.id],selected=session.responses[question.id]||[],inlineSelected=session.inlineSelections[question.id]||[],choiceMarks=session.choiceMarks[question.id]||[],phase=result?'submitted':'solving',displayPrompt=question.writingGuide?.title||question.prompt,extras=new Set(question.renderSpec?.extras||[]),showStimulus=question.stimulus&&extras.has('stimulus'),showSummary=question.summaryText&&extras.has('summary'),showPassage=question.interactionContract?.passage?.visible,outcome=questionOutcome(question,result),lookupSentences=[],lookupEnabled=!!result?.persisted;
  const lookupText=lookupEnabled?(text,surfaceKey)=>{const id=`question:${question.id}:${surfaceKey}`,sentence={id,text:String(text||''),lookupContext:{surfaceKind:'question',surfaceKey,questionId:question.id}};lookupSentences.push(sentence);return readerGlossSentenceHtml(sentence);}:null,root=$('#student-questions'),promptLookup=lookupText&&displayPrompt===question.prompt,difficultyCopy=question.referenceQuestionNo?`Ref ${question.referenceQuestionNo} · ${questionDifficultyKoreanLabel(question.difficulty)}`:questionDifficultyLabel(question.difficulty);show('student-questions');root.innerHTML=`<button class="study-back" type="button" data-exit-questions aria-label="Home으로"><span aria-hidden="true">‹</span></button><div class="question-layout" data-question-phase="${phase}"><div class="reader-shell"><div class="question-topline"><span class="question-progress">${question.source?.passageNo?`${question.source.passageNo}번 · `:''}${session.index+1} / ${session.items.length}</span><div class="question-state"><span class="question-difficulty-badge difficulty-${esc(question.difficulty)}">${esc(difficultyCopy)}</span><span class="question-result-dot ${outcome}" role="img" aria-label="${outcome==='correct'?'맞힌 문제':outcome==='wrong'?'틀린 문제':'아직 풀지 않은 문제'}"></span><button class="question-bookmark ${question.bookmarked?'active':''}" type="button" data-toggle-bookmark aria-pressed="${!!question.bookmarked}" aria-label="${question.bookmarked?'Review에서 제거':'Review에 저장'}">${bookmarkIcon(question.bookmarked)}</button></div></div><p class="eyebrow">PASSAGE · ${esc((question.renderer||question.family||'standard').toUpperCase())}</p>${showStimulus?`<section class="question-stimulus"><strong>주어진 문장</strong>${esc(question.stimulus)}</section>`:''}${showPassage?`<article class="reading-passage question-passage">${questionPassageHtml(question,result,selected,inlineSelected,lookupText)}</article>`:''}<h1 class="question-prompt">${promptLookup?lookupText(displayPrompt,'prompt'):esc(displayPrompt)}</h1>${showSummary?`<section class="question-summary">${questionSummaryHtml(question)}</section>`:''}${responseArea(question,result,selected,choiceMarks,lookupText)}<div class="question-submit-row">${result?resultFeedbackHtml(question,result):questionAiStatusHtml(session,question,hasResponse(question,selected,inlineSelected))}</div><p class="reader-inline-notice" data-reader-gloss-notice hidden></p><span class="sr-only" data-reader-gloss-live aria-live="polite"></span><div class="shorts-cue"><button class="button quiet small" type="button" data-question-prev aria-label="이전 문제" ${session.index===0?'disabled':''}>↑</button><small>${session.index===session.items.length-1?'마지막 문제':'위아래로 넘겨 이동'}</small><button class="button quiet small" type="button" data-question-next aria-label="다음 문제" ${session.index===session.items.length-1?'disabled':''}>↓</button></div></div></div>`;if(lookupEnabled)attachWordLookup(root,{id:question.passageId,updated_at:`question:${question.id}`},lookupSentences);}
function startQuestionSession(items,mode='passage'){state.questionSession={items,index:0,responses:{},inlineSelections:{},choiceMarks:{},results:{},aiPending:{},aiErrors:{},persistenceSequence:{},startedAt:performance.now(),mode};renderQuestion();}
async function openQuestions(passageId){if(!state.scope)return;const data=await safely(()=>call('student_questions',{examId:state.scope.id,passageId},state.token,'문제를 준비하는 중…'));if(!data)return;if(!data.questions?.length){toast('이 지문의 새 문제를 모두 풀었습니다.');return loadDashboard();}applyPassage(data);startQuestionSession(data.questions.map(question=>({...question,passageText:question.passageText||plainPassage()})));}
function reviewMemoryHtml(levelValue){const level=Math.max(1,Math.min(3,Number(levelValue)||1));return `<span class="word-review-memory" data-memory-level="${level}"><b>LEVEL ${level}</b><span class="word-review-level-bars" aria-hidden="true"><i></i><i></i><i></i></span></span>`;}
function reviewWordHtml(item){const examples=item.examples||[],senses=item.senses?.length?item.senses:[{id:item.id,meaning:item.meaning}];return `<details class="word-review-item review-word" data-review-word-id="${esc(item.id)}"><summary class="word-review-summary"><span class="word-review-term"><strong class="word-review-lemma">${esc(item.lemma)}</strong><span class="word-review-meaning">${senses.map(sense=>esc(sense.meaning)).join('<br>')}</span><small>예문 ${item.exampleCount??examples.length}개</small></span>${reviewMemoryHtml(item.memoryLevel)}<span class="word-review-chevron" aria-hidden="true">⌄</span></summary><div class="word-review-detail review-word-detail"><section class="review-word-contexts"><div class="review-detail-heading"><p class="eyebrow">EXAMPLES <b>${String(examples.length).padStart(2,'0')}</b></p></div>${examples.length?`<div class="word-context-history">${examples.map(example=>`<article class="word-context-row"><div><strong>${esc(example.sourceSpan)}</strong><span class="word-context-gloss">당시 뜻 · ${esc(example.meaning)}</span></div><div><p class="word-context-en" lang="en">${esc(example.englishSentence)}</p>${example.publisherTranslation?`<p class="word-context-ko">${esc(example.publisherTranslation)}</p>`:''}<small>${esc(example.passageTitle||example.sourceLabel||'READY')} · ${esc(example.sourceKind||'reader')}</small></div></article>`).join('')}</div>`:'<p class="review-empty-copy">저장 후 다른 문맥에서 찾아본 예문이 아직 없습니다.</p>'}</section><section class="review-word-controls"><button class="word-review-remove" type="button" data-review-word-remove="${esc(item.lemma)}">단어 제거</button></section></div></details>`;}
function reviewNavHtml(counts,active){return `<nav class="word-review-nav" aria-label="Review 유형">${[['word','WORD'],['sentence','SENTENCE'],['workbook','WORKBOOK'],['question','QUESTION']].map(([kind,label])=>`<button class="word-review-tab${active===kind?' is-active':''}" type="button" data-review-kind="${kind}" aria-current="${active===kind?'page':'false'}"><span>${label}</span><b>${Number(counts[kind])||0}</b></button>`).join('')}</nav>`;}
function reviewPanelHtml(kind,{questions,workbooks,words,sentences,counts}){
  if(kind==='word')return `<section class="review-panel word-review-panel"><header class="review-panel-head"><div><p class="eyebrow">WORD</p><h2>단어장</h2></div><small>${Number(counts.word)||0}개 저장됨</small></header>${words.length?`<div class="word-review-list">${words.map(reviewWordHtml).join('')}</div>`:'<div class="review-panel-empty">저장한 단어가 없습니다.</div>'}</section>`;
  if(kind==='sentence')return `<section class="review-panel sentence-review-panel"><header class="review-panel-head"><div><p class="eyebrow">SENTENCE</p><h2>저장한 문장</h2></div><small>${Number(counts.sentence)||0}개 저장됨</small></header>${sentences.length?`<div class="review-sentence-list">${sentences.map(item=>`<article><p lang="en">${esc(item.source_text_snapshot)}</p><p>${esc(item.translation_snapshot)}</p><small>${esc(item.passage?.title||'READY Reader')}</small></article>`).join('')}</div>`:'<div class="review-panel-empty">저장한 문장이 없습니다.</div>'}</section>`;
  if(kind==='workbook')return `<section class="review-panel workbook-review-panel"><header class="review-panel-head"><div><p class="eyebrow">WORKBOOK</p><h2>본문 체화</h2></div><small>${Number(counts.workbook)||0}개 복습</small></header>${workbooks.length?`<div class="review-workbook-list">${workbooks.map(item=>`<button type="button" data-review-workbook-passage="${item.passageId}" data-review-workbook-item="${item.itemKey}"><span><strong>${esc(item.title)} · ${item.number}</strong><small>${esc(item.passageTitle)} · ${item.lastResult===false?'오답':'북마크'}</small></span><b>›</b></button>`).join('')}</div>`:'<div class="review-panel-empty">복습할 워크북 문제가 없습니다.</div>'}</section>`;
  return `<section class="review-panel question-review-panel"><header class="review-panel-head"><div><p class="eyebrow">QUESTION</p><h2>시험 문제</h2></div><small>${Number(counts.question)||0}개 복습</small></header>${questions.length?`<div class="review-question-cta"><span><strong>${questions.length}문제를 다시 풀어보세요.</strong><small>오답과 저장한 문제를 Shorts 방식으로 복습합니다.</small></span><button class="button primary" type="button" data-start-review-questions>다시 풀기</button></div>`:'<div class="review-panel-empty">복습할 시험 문제가 없습니다.</div>'}</section>`;
}
function renderReview(){const data=state.reviewData;if(!data)return renderScope();const questions=data.items||[],workbooks=data.workbookItems||[],words=data.wordItems||[],sentences=data.sentenceItems||[],counts=data.counts||{word:words.length,sentence:sentences.length,workbook:workbooks.length,question:questions.length},kind=['word','sentence','workbook','question'].includes(state.reviewKind)?state.reviewKind:'word',titles={word:['Word Review','저장한 단어를 다시 확인하세요.'],sentence:['Sentence Review','저장한 문장을 다시 확인하세요.'],workbook:['Workbook Review','다시 볼 워크북 학습을 모았습니다.'],question:['Question Review','저장한 문제와 오답을 다시 풀어보세요.']},[title,description]=titles[kind];show('student-review');$('#student-review').innerHTML=`<div class="review-head"><div><p class="eyebrow">READY · REVIEW</p><h1>${title}</h1><small>${description}</small></div><button class="review-export-open" type="button" data-open-review-export>PDF 만들기</button></div><div class="word-review-dashboard">${reviewNavHtml(counts,kind)}${reviewPanelHtml(kind,{questions,workbooks,words,sentences,counts})}</div>`;}
async function openReview(){if(!state.scope)return;const data=await safely(()=>call('student_review_questions',{examId:state.scope.id},state.token,'Review를 준비하는 중…'));if(!data)return;state.reviewData=data;state.reviewCount=Object.values(data.counts||{}).reduce((sum,value)=>sum+(Number(value)||0),0);updateStudentNav();renderReview();}
